import type { jsPDF } from 'jspdf';

// Fonte Nexa Regular (TrueType base64)
export const NEXA_REGULAR_BASE64 = '';

// Fonte Nexa Bold (TrueType base64)
export const NEXA_BOLD_BASE64 = '';

// Fonte Nexa Italic (TrueType base64)
export const NEXA_ITALIC_BASE64 = '';

/**
 * Registra a família tipográfica Nexa no documento jsPDF (normal, bold e italic)
 */
export function registerNexaFonts(doc: jsPDF): void {
  try {
    const fontList = doc.getFontList();
    if (!fontList['Nexa']) {
      doc.addFileToVFS('Nexa-Regular.ttf', NEXA_REGULAR_BASE64);
      doc.addFont('Nexa-Regular.ttf', 'Nexa', 'normal');

      doc.addFileToVFS('Nexa-Bold.ttf', NEXA_BOLD_BASE64);
      doc.addFont('Nexa-Bold.ttf', 'Nexa', 'bold');

      doc.addFileToVFS('Nexa-Italic.ttf', NEXA_ITALIC_BASE64);
      doc.addFont('Nexa-Italic.ttf', 'Nexa', 'italic');
    }
  } catch (err) {
    console.warn('Aviso ao registrar fonte Nexa no jsPDF:', err);
  }
}
